def transform(grid):
    out=[row[:] for row in grid]
    colors={v for row in grid for v in row}
    # Find a one-cell interruption in a straight line of the non-background shape.
    # Background is the most common color; replacement uses ARC color 2 as in the demo.
    bg=max(colors, key=lambda x: sum(row.count(x) for row in grid))
    shape={v for v in colors if v!=bg}
    if not shape: return out
    # Among gaps enclosed by the same color on opposite sides, choose the one
    # whose enclosing line contains the greatest number of shape cells.
    candidates=[]
    h=len(grid); w=len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in shape: continue
            for dr,dc in ((1,0),(0,1)):
                rr,cc=r+dr,c+dc
                while rr<h and cc<w:
                    if grid[rr][cc] in shape:
                        # Only a single-cell gap is considered; this scan has no gaps.
                        break
                    # Stop at a gap candidate only when next cell along the axis is shape.
                    nr,nc=rr+dr,cc+dc
                    if nr<h and nc<w and grid[nr][nc] in shape:
                        # Matching color endpoints, and gap cell is background.
                        if grid[r][c]==grid[nr][nc] and grid[rr][cc]==bg:
                            # Count contiguous line length on both sides.
                            count=2; ar,ac=r-dr,c-dc
                            while 0<=ar<h and 0<=ac<w and grid[ar][ac]==grid[r][c]:
                                count+=1; ar-=dr; ac-=dc
                            ar,ac=nr+dr,nc+dc
                            while ar<h and ac<w and grid[ar][ac]==grid[r][c]:
                                count+=1; ar+=dr; ac+=dc
                            candidates.append((count,r,c,rr,cc))
                        break
                    # Gaps longer than one are not candidates.
                    break
    if candidates:
        _,r,c,rr,cc=max(candidates)
        out[rr][cc]=2
    return out

