def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = {}
    for row in grid:
        for v in row: freq[v] = freq.get(v, 0) + 1
    bg = max(freq, key=freq.get)
    fg = next(v for v in freq if v != bg)
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == fg]
    if not pts: return [row[:] for row in grid]
    rmin=min(r for r,c in pts); rmax=max(r for r,c in pts)
    cmin=min(c for r,c in pts); cmax=max(c for r,c in pts)
    out=[row[:] for row in grid]
    # Fill the foreground's bounding horizontal and vertical spans.
    for r in range(h):
        if any(grid[r][c] == fg for c in range(w)):
            for c in range(cmin,cmax+1):
                if grid[r][c] == bg: out[r][c]=2
    for c in range(w):
        if any(grid[r][c] == fg for r in range(h)):
            for r in range(rmin,rmax+1):
                if grid[r][c] == bg: out[r][c]=2
    return out
